"""Regenerate assets/CATALOG.md: every asset already downloaded/usable in this project, one line each.
Agents read CATALOG.md BEFORE searching or downloading anything (token rule, see AGENTS.md).

  python pipeline/tools/catalog.py
"""

import json
import sys
from collections import Counter
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from paths import ROOT
A = ROOT / "assets"
L = [
    "# Asset catalog (auto-generated by `python pipeline/catalog.py` - do not edit by hand)",
    "",
    "Check here before searching Polyfork/Roblox. Re-run the script after downloading anything.",
    "",
]

# ---- Polyfork kits
L += ['## Polyfork kits (`assets/models/kits/<kit>/`, metres, use as `"set": "kit", "setOpts": {"kit": "<kit>"}`)', ""]
for kd in sorted(
    p
    for p in (A / "models" / "kits").glob("*")
    if p.is_dir() and (p / "kit.mjs").exists() and not (p.name.startswith("kit-") and (p.parent / p.name[4:]).exists())
):
    parts = json.loads((kd / "PARTS.json").read_text(encoding="utf-8")) if (kd / "PARTS.json").exists() else {}
    lay = json.loads((kd / "LAYOUT.json").read_text(encoding="utf-8")) if (kd / "LAYOUT.json").exists() else []
    used = Counter(r["part"] for r in lay if r.get("part") != "_terrain")
    title = (
        next(
            (ln[2:].strip() for ln in (kd / "KIT.md").read_text(encoding="utf-8").splitlines() if ln.startswith("# ")),
            kd.name,
        )
        if (kd / "KIT.md").exists()
        else kd.name
    )
    L += [
        f"### {title} - `{kd.name}`",
        f"{len(parts)} parts, {sum(used.values())} placements in the composed place. Parts (class, xN = times placed in LAYOUT):",
        "",
    ]
    by = {}
    for k, v in parts.items():
        by.setdefault(v.get("class", "?"), []).append(f"{k}" + (f" x{used[k]}" if used.get(k) else ""))
    for c in sorted(by):
        L.append(f"- **{c}**: " + ", ".join(sorted(by[c])))
    L.append("")

# ---- Categorized low-poly models
mod_dir = A / "models"
if mod_dir.exists():
    L += ["## Low-poly Models by Category (`assets/models/<category>/<id>.glb`)", ""]
    for cat_dir in sorted(p for p in mod_dir.glob("*") if p.is_dir()):
        man_file = cat_dir / "manifest.json"
        cat_meta = json.loads(man_file.read_text(encoding="utf-8")) if man_file.exists() else {}
        cat_title = cat_meta.get("title", cat_dir.name.replace("_", " ").title())
        desc = cat_meta.get("description", "")
        models = cat_meta.get("models", [])
        glbs = sorted(cat_dir.glob("*.glb"))
        L += [f"### {cat_title} (`assets/models/{cat_dir.name}/`)", f"{len(glbs)} models. {desc}".strip(), ""]
        if models:
            items = [f"`{m['id']}` ({m['title']})" for m in models]
            L.append("- " + ", ".join(items))
        else:
            L.append("- " + ", ".join(f"`{g.stem}`" for g in glbs))
        L.append("")

# ---- Roblox hair
hc = ROOT / "config" / "roblox_hair.json"
if hc.exists():
    L += ['## Roblox hair (`"hair": "rbx:<id>"`, from assets/roblox/hair.obj)', ""]
    names = {
        7259123616: "black messy (covers eyes)",
        6501746646: "blonde/brown long girl",
        376524487: "blonde spiked",
        376548738: "brown charmer",
        376527350: "black ponytail",
        2956239660: "long red",
        63690008: "pal hair (brown)",
        451221329: "true blue",
        376526888: "straight blonde",
        1103003368: "orange beanie + black hair",
        16630147: "beautiful hair (brown long)",
    }
    L += [", ".join(f"`{i}` {names.get(i, '')}".strip() for i in json.loads(hc.read_text())["hair"]), ""]

# ---- audio
for kind, title in (("sfx", "SFX files (`sfx: [{name}]`)"), ("music", "Music files (`music`)")):
    fs = sorted(p.stem for p in (A / "audio" / kind).glob("*") if p.is_file())
    if fs:
        L += [f"## {title}", ", ".join(fs), ""]
vs = sorted(p.stem for p in (A / "audio" / "voices").glob("*.wav"))
if vs:
    L += ["## Voice reference clips (local TTS, mapped in config/voices.json)", ", ".join(vs), ""]

(A / "CATALOG_FULL.md").write_text("\n".join(L), encoding="utf-8")

# ---- Compact index = what agents read. Per kit only landmarks (buildings + vehicles); every part is in CATALOG_FULL.md (grep it, never read it whole).
S = [
    "# Asset index (auto-generated by `python pipeline/catalog.py` - do not edit by hand)",
    "",
    "Ready-made locations: `config/locations.json` (use those first). Cast presets: `config/cast.json`.",
    'Kits + landmark parts, usable as `near` in a new location: `{"setOpts": {"kit": "<kit>", "near": "<part>", "dz": 6}}`.',
    "Small parts (props, furniture) and the model list: grep `assets/CATALOG_FULL.md`, don't read it.",
    "",
    "## Kits",
]
for kd in sorted(
    p
    for p in (A / "models" / "kits").glob("*")
    if p.is_dir() and (p / "kit.mjs").exists() and not (p.name.startswith("kit-") and (p.parent / p.name[4:]).exists())
):
    parts = json.loads((kd / "PARTS.json").read_text(encoding="utf-8"))
    used = Counter(r["part"] for r in json.loads((kd / "LAYOUT.json").read_text(encoding="utf-8")))
    lm = (
        sorted(k for k, v in parts.items() if v.get("class") in ("building", "vehicle") and used.get(k))
        or sorted(k for k in parts if used.get(k))[:12]
    )
    S.append(f"- `{kd.name}`: " + " ".join(lm))
if mod_dir.exists():
    S += [
        "",
        "## Models (`assets/models/<category>/`)",
        ", ".join(f"{d.name} ({len(list(d.glob('*.glb')))})" for d in sorted(mod_dir.glob("*")) if d.is_dir()),
    ]
i = next((n for n, x in enumerate(L) if x.startswith("## Roblox hair")), len(L))
S += [""] + L[i:]
(A / "CATALOG.md").write_text("\n".join(S), encoding="utf-8")
print(f"CATALOG.md: {len(S)} lines (index) · CATALOG_FULL.md: {len(L)} lines")
